#!/usr/bin/env node
/**
 * Builds the demo project used for screenshots and manual testing.
 *
 * Everything here is invented: channel names, plugin names, vendors, colours.
 * Nothing comes from a real user's music, so the generated file is safe to ship
 * in a public repository and to open in the app for a quick look.
 *
 *   node scripts/make-demo.mjs docs/demo.flp
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import {
  ascii,
  event,
  note,
  playlistItem,
  u16,
  u32,
  utf16,
  vstState,
  wrapFlp,
} from './lib/flp-writer.mjs';

// kind: 0 sampler · 1 hybrid · 2 instrument · 3 layer · 4 audio clip · 5 automation
const CHANNELS = [
  { name: 'Bass', kind: 2, color: 0x004a9eff, vst: { name: 'NovaSynth', vendor: 'Demo Audio', path: 'C:\\VST\\NovaSynth.dll' } },
  { name: 'Lead', kind: 2, color: 0x00e8a33d, vst: { name: 'NovaSynth', vendor: 'Demo Audio', path: 'C:\\VST\\NovaSynth.dll' } },
  { name: 'Pad', kind: 2, color: 0x0045c08a, vst: { name: 'GlassPad', vendor: 'Demo Audio', path: 'C:\\VST\\GlassPad.vst3' } },
  { name: 'Kick', kind: 0, color: 0x00e05c5c },
  { name: 'Snare', kind: 0, color: 0x00e05c5c },
  { name: 'Hat', kind: 0, color: 0x00e05c5c },
  { name: 'Vocal Chop', kind: 4, color: 0x009b7fd6 },
  { name: 'FX Riser', kind: 4, color: 0x009b7fd6 },
  { name: 'Cutoff', kind: 5, color: 0x00e8a33d },
  { name: 'Reverb Mix', kind: 5, color: 0x00e8a33d },
  { name: 'Drum Bus', kind: 3, color: 0x007f8fa6 },
  { name: 'MIDI Out', kind: 2, color: 0x007f8fa6 },
];

const PATTERNS = [
  {
    name: 'Intro',
    color: 0x004a9eff,
    notes: [
      [0, 48, 96], [96, 55, 96], [192, 60, 96], [288, 64, 96],
      [384, 60, 192], [576, 55, 192],
    ],
  },
  {
    name: 'Verse',
    color: 0x0045c08a,
    notes: [
      [0, 36, 48], [96, 36, 48], [192, 43, 48], [288, 43, 48],
      [384, 41, 48], [480, 41, 48], [576, 43, 48], [672, 43, 48],
      [768, 36, 96], [864, 39, 96], [960, 43, 96], [1056, 48, 96],
    ],
  },
  {
    name: 'Chorus',
    color: 0x00e8a33d,
    notes: [
      [0, 60, 48], [48, 64, 48], [96, 67, 48], [144, 72, 96],
      [240, 67, 48], [288, 64, 48], [336, 60, 96], [432, 55, 48],
      [480, 60, 96], [576, 64, 48], [624, 67, 48], [672, 72, 192],
      [864, 76, 96], [960, 72, 96], [1056, 67, 96], [1152, 60, 192],
    ],
  },
  {
    name: 'Break',
    color: 0x009b7fd6,
    notes: [[0, 55, 384], [384, 57, 384], [768, 59, 192], [960, 55, 384]],
  },
];

const TRACKS = [
  { index: 1, name: 'Arrangement' },
  { index: 2, name: 'Vocals' },
  { index: 3, name: 'FX' },
  { index: 4, name: 'Automation' },
];

const CLIPS = [
  { pattern: 0, position: 0, length: 576, track: 1 },
  { pattern: 1, position: 576, length: 1152, track: 1 },
  { pattern: 2, position: 1728, length: 1152, track: 1 },
  { pattern: 1, position: 2880, length: 576, track: 1 },
  { pattern: 3, position: 3456, length: 768, track: 1 },
  { channel: 6, position: 576, length: 384, track: 2 },
  { channel: 6, position: 1728, length: 576, track: 2 },
  { channel: 7, position: 0, length: 192, track: 3 },
  { channel: 7, position: 3456, length: 384, track: 3 },
  { channel: 8, position: 0, length: 4224, track: 4 },
  { channel: 9, position: 2592, length: 384, track: 4 },
];

// insert 0 is always Master in FL.
const INSERTS = [
  { name: 'Master', color: 0x007e6e68, slots: ['Demo Limiter'] },
  { name: 'Drums', color: 0x00e05c5c, slots: ['Demo EQ 2', 'Demo Comp'] },
  { name: 'Bass', color: 0x004a9eff, slots: ['Demo EQ 2'] },
  { name: 'Synth', color: 0x00e8a33d, slots: ['Demo Reverb', 'Demo Delay'] },
  { name: 'Vocal', color: 0x009b7fd6, slots: ['Demo EQ 2', 'Demo Comp'] },
  { name: 'FX', color: 0x0045c08a, slots: ['Demo Reverb'] },
  { name: 'Bus', color: 0x007f8fa6, slots: ['Demo Clipper'] },
  { name: 'Send', color: 0x00c0a04a, slots: ['Demo Reverb'] },
];

const events = [
  event(199, ascii('25.1.4.4951')),
  event(17, [4]),
  event(18, [4]),
  event(35, [1]),
  event(156, u32(128000)), // 128.000 BPM
  event(194, utf16('Demo Project')), // title
  event(195, utf16('Generated by scripts/make-demo.mjs — every value is synthetic.')),
  event(206, utf16('Demo')),
  event(207, utf16('FlpLens')),

  ...CHANNELS.flatMap((channel, index) => {
    const out = [event(64, u16(index)), event(21, [channel.kind]), event(128, u32(channel.color))];
    // Event 219: pan i32, volume u32, pitch i32, 12 opaque bytes. 12800 = full
    // scale, pan centred at 6400 — the values FL itself writes.
    const pan = 6400 + Math.round((index % 3 === 0 ? -0.35 : index % 3 === 1 ? 0.25 : 0) * 6400);
    const volume = 12800 - (index % 4) * 900;
    out.push(
      event(219, [...u32(pan), ...u32(volume), ...u32(0), ...new Array(12).fill(0)]),
    );
    if (channel.vst) {
      out.push(event(201, utf16('Plugin Wrapper')));
      out.push(event(203, utf16(channel.name)));
      out.push(event(213, vstState(channel.vst)));
    } else if (channel.kind === 4) {
      out.push(event(203, utf16(channel.name)));
      out.push(event(196, utf16(`C:\\Samples\\${channel.name}.wav`)));
    } else {
      out.push(event(203, utf16(channel.name)));
    }
    return out;
  }),

  ...PATTERNS.flatMap((pattern, index) => [
    event(65, u16(index)),
    event(193, utf16(pattern.name)),
    event(150, u32(pattern.color)),
    event(224, pattern.notes.flatMap(([position, key, length], step) =>
      note({
        position,
        length,
        key,
        channel: (index + step) % 3,
        velocity: 55 + ((step * 17 + index * 11) % 72),
        pan: 64 + Math.round(Math.sin(step + index) * 40),
      }),
    )),
  ]),

  event(99, u16(0)),
  event(241, utf16('Arrangement')),
  event(233, CLIPS.flatMap((clip) => playlistItem(clip))),

  ...TRACKS.flatMap((track) => [
    event(238, [...u32(track.index), ...new Array(62).fill(0)]),
    event(239, utf16(track.name)),
  ]),

  ...INSERTS.flatMap((insert, insertIndex) => {
    const out = [event(236, u32(0)), event(204, utf16(insert.name)), event(149, u32(insert.color))];
    insert.slots.forEach((slot, slotIndex) => {
      out.push(event(98, u16(slotIndex)));
      out.push(event(201, utf16(slot)));
    });
    // An empty tail slot, so the UI's "loaded only" filter has something to do.
    out.push(event(98, u16(insert.slots.length)));
    if (insertIndex === 0) out.push(event(201, utf16('Demo Balance')));
    return out;
  }),
];

const bytes = wrapFlp(events, { numChannels: CHANNELS.length, ppq: 96 });
const out = process.argv[2] || 'docs/demo.flp';
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, bytes);
console.log(
  `${out} (${(bytes.length / 1024).toFixed(1)} KB, ${CHANNELS.length} channels, ` +
    `${PATTERNS.length} patterns, ${CLIPS.length} clips, ${INSERTS.length} inserts)`,
);
